import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  completed INTEGER NOT NULL DEFAULT 0,
  result_output TEXT,
  error TEXT,
  idempotency_key TEXT UNIQUE,
  payload TEXT,
  run_after INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, run_after, seq);
CREATE TABLE IF NOT EXISTS worker_heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  beat_at INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}
import { randomUUID } from 'node:crypto';
import type { DatabaseSync, StatementSync } from 'node:sqlite';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export const MAX_ATTEMPTS = 3;
export const TRANSIENT_ERROR = 'transient failure';
/** A worker that has not written a heartbeat for this long is reported as down. */
export const HEARTBEAT_STALE_MS = 3_000;

export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

interface Row {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  payload: string | null;
  created_at: string;
  updated_at: string;
}

export interface ClaimedJob {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  /** The attempt number now running (1-based). */
  attempt: number;
}

function toJob(row: Row): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** All job and heartbeat state access. Used by both the server and the worker. */
export class Store {
  private readonly insert: StatementSync;
  private readonly selectById: StatementSync;
  private readonly selectByKey: StatementSync;
  private readonly selectAll: StatementSync;
  private readonly selectNext: StatementSync;
  private readonly startAttempt: StatementSync;
  private readonly updateProgress: StatementSync;
  private readonly complete: StatementSync;
  private readonly failToFailed: StatementSync;
  private readonly failToQueued: StatementSync;
  private readonly recover: StatementSync;
  private readonly beat: StatementSync;
  private readonly selectBeat: StatementSync;
  private readonly clearBeat: StatementSync;

  constructor(private readonly db: DatabaseSync) {
    this.insert = db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, payload, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
    );
    this.selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
    this.selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
    this.selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
    this.selectNext = db.prepare(
      "SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1",
    );
    this.startAttempt = db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE id = ?",
    );
    this.updateProgress = db.prepare(
      "UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND attempts = ? AND status = 'running'",
    );
    this.complete = db.prepare(
      "UPDATE jobs SET status = 'completed', result_output = ?, completed = steps, updated_at = ? WHERE id = ? AND attempts = ? AND status = 'running'",
    );
    this.failToFailed = db.prepare(
      "UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ? AND attempts = ? AND status = 'running'",
    );
    this.failToQueued = db.prepare(
      "UPDATE jobs SET status = 'queued', completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND attempts = ? AND status = 'running'",
    );
    this.recover = db.prepare(
      "UPDATE jobs SET status = 'queued', completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
    );
    this.beat = db.prepare(
      'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT (id) DO UPDATE SET beat_at = excluded.beat_at',
    );
    this.selectBeat = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1');
    this.clearBeat = db.prepare('DELETE FROM worker_heartbeat WHERE id = 1');
  }

  createJob(input: string, steps: number, failAttempts: number, key: string | null, payload: string | null): Job {
    const id = randomUUID();
    const now = new Date().toISOString();
    this.insert.run(id, input, steps, failAttempts, key, payload, now, now);
    return this.getJob(id)!;
  }

  getJob(id: string): Job | undefined {
    const row = this.selectById.get(id) as unknown as Row | undefined;
    return row ? toJob(row) : undefined;
  }

  /** Returns the job created under an idempotency key, with the payload it was created from. */
  findByKey(key: string): { job: Job; payload: string | null } | undefined {
    const row = this.selectByKey.get(key) as unknown as Row | undefined;
    return row ? { job: toJob(row), payload: row.payload } : undefined;
  }

  listJobs(): Job[] {
    return (this.selectAll.all() as unknown as Row[]).map(toJob);
  }

  writeHeartbeat(now: number): void {
    this.beat.run(now);
  }

  clearHeartbeat(): void {
    this.clearBeat.run();
  }

  workerUp(now: number): boolean {
    const row = this.selectBeat.get() as { beat_at: number } | undefined;
    return row !== undefined && now - row.beat_at < HEARTBEAT_STALE_MS;
  }

  /** Requeues jobs left `running` by a worker that stopped without finishing them. Returns how many. */
  recoverInterrupted(now: number): number {
    return Number(this.recover.run(now).changes);
  }

  /** Moves the oldest eligible queued job to running and starts a new attempt. */
  claimNext(now: number): ClaimedJob | undefined {
    return this.transaction(() => {
      const next = this.selectNext.get(now) as { id: string } | undefined;
      if (!next) return undefined;
      this.startAttempt.run(now, next.id);
      const row = this.selectById.get(next.id) as unknown as Row;
      return {
        id: row.id,
        input: row.input,
        steps: row.steps,
        failAttempts: row.fail_attempts,
        attempt: row.attempts,
      };
    });
  }

  reportProgress(id: string, attempt: number, completed: number): void {
    this.updateProgress.run(completed, new Date().toISOString(), id, attempt);
  }

  finishCompleted(id: string, attempt: number, output: string): void {
    this.complete.run(output, new Date().toISOString(), id, attempt);
  }

  /** Records a failed attempt: requeues it with a delay, or marks it failed when no attempts remain. */
  finishFailedAttempt(id: string, attempt: number, retryAt: number): 'queued' | 'failed' {
    const now = new Date().toISOString();
    if (attempt >= MAX_ATTEMPTS) {
      this.failToFailed.run(TRANSIENT_ERROR, now, id, attempt);
      return 'failed';
    }
    this.failToQueued.run(retryAt, now, id, attempt);
    return 'queued';
  }

  private transaction<T>(fn: () => T): T {
    this.db.exec('BEGIN IMMEDIATE');
    try {
      const result = fn();
      this.db.exec('COMMIT');
      return result;
    } catch (e) {
      this.db.exec('ROLLBACK');
      throw e;
    }
  }
}
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { Store } from './store.ts';

/** Time for one simulated processing step. */
const STEP_MS = 100;
const HEARTBEAT_MS = 1_000;
const IDLE_POLL_MS = 200;
const ERROR_BACKOFF_MS = 500;
/** Retry delay is drawn from this range (inclusive of the lower bound, exclusive of the upper). */
const RETRY_MIN_MS = 250;
const RETRY_MAX_MS = 2_000;

const db = openDatabase();
const store = new Store(db);
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Processes one attempt of the oldest eligible job. Returns false when there was nothing to do. */
async function processNext(): Promise<boolean> {
  const job = store.claimNext(Date.now());
  if (!job) return false;

  if (job.attempt <= job.failAttempts) {
    // Simulated transient failure at the first step, before any progress.
    await sleep(STEP_MS);
    const retryAt = Date.now() + RETRY_MIN_MS + Math.floor(Math.random() * (RETRY_MAX_MS - RETRY_MIN_MS));
    store.finishFailedAttempt(job.id, job.attempt, retryAt);
    return true;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return true; // Left running; the next start requeues it.
    store.reportProgress(job.id, job.attempt, step);
  }
  store.finishCompleted(job.id, job.attempt, job.input.toUpperCase());
  return true;
}

const recovered = store.recoverInterrupted(Date.now());
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);
store.writeHeartbeat(Date.now());
const heartbeat = setInterval(() => store.writeHeartbeat(Date.now()), HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    if (await processNext()) continue;
  } catch (e) {
    console.error(`worker error: ${e instanceof Error ? e.message : String(e)}`);
    await sleep(ERROR_BACKOFF_MS);
    continue;
  }
  await sleep(IDLE_POLL_MS);
}

clearInterval(heartbeat);
store.clearHeartbeat();
db.close();
console.log('worker stopped');
export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ParsedSubmission =
  | { ok: true; value: Submission; key: string | undefined; payload: string }
  | { ok: false; fields: FieldError[] };

const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
/** Bodies larger than this are rejected without parsing. */
export const MAX_BODY_BYTES = 64 * 1024;

function integerField(obj: Record<string, unknown>, name: 'steps' | 'failAttempts', min: number, max: number, fallback: number, errors: FieldError[]): number {
  const v = obj[name];
  if (v === undefined) return fallback;
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return v;
}

/** Validates a submission's headers and raw body. `rawBody` is null when the body was too large. */
export function parseSubmission(contentType: string | undefined, rawBody: string | null, idempotencyKey: string | undefined): ParsedSubmission {
  const fields: FieldError[] = [];
  let key: string | undefined;
  if (idempotencyKey !== undefined) {
    if (KEY_PATTERN.test(idempotencyKey)) key = idempotencyKey;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const mediaType = contentType?.split(';')[0]?.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return { ok: false, fields };
  }
  if (rawBody === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
    return { ok: false, fields };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    fields.push({ field: 'body', message: 'body must be valid JSON' });
    return { ok: false, fields };
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return { ok: false, fields };
  }

  const obj = parsed as Record<string, unknown>;
  for (const name of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(name)) fields.push({ field: name, message: 'unknown field' });
  }

  const input = obj.input;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'must not be blank' });
  }

  const steps = integerField(obj, 'steps', 1, 20, 5, fields);
  const failAttempts = integerField(obj, 'failAttempts', 0, 5, 0, fields);

  if (fields.length > 0 || typeof input !== 'string') return { ok: false, fields };
  const value = { input, steps, failAttempts };
  return { ok: true, value, key, payload: JSON.stringify([input, steps, failAttempts]) };
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { Store } from './store.ts';
import { MAX_BODY_BYTES, parseSubmission, type FieldError } from './validation.ts';

const db = openDatabase();
const store = new Store(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } }, headers);
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allow}.`, undefined, { allow });
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', () => resolve(null));
  });
}

async function createJobFromRequest(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawBody = await readBody(req);
  const header = req.headers['idempotency-key'];
  const parsed = parseSubmission(req.headers['content-type'], rawBody, typeof header === 'string' ? header : undefined);
  if (!parsed.ok) {
    return sendError(res, 400, 'invalid_request', 'The request is invalid.', parsed.fields);
  }

  if (parsed.key !== undefined) {
    const existing = store.findByKey(parsed.key);
    if (existing) {
      if (existing.payload === parsed.payload) return send(res, 200, existing.job);
      return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    }
  }

  const { input, steps, failAttempts } = parsed.value;
  const job = store.createJob(input, steps, failAttempts, parsed.key ?? null, parsed.key !== undefined ? parsed.payload : null);
  send(res, 201, job, { location: `/api/jobs/${job.id}` });
}

function handle(req: IncomingMessage, res: ServerResponse): void {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return send(res, 200, { status: 'ok', worker: store.workerUp(Date.now()) ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: store.listJobs() });
    if (method === 'POST') {
      createJobFromRequest(req, res).catch(() => {
        if (!res.headersSent) sendError(res, 500, 'internal_error', 'Unexpected server error.');
      });
      return;
    }
    return methodNotAllowed(res, 'GET, POST');
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const job = store.getJob(id);
    return job ? send(res, 200, job) : sendError(res, 404, 'not_found', 'No such job.');
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  try {
    handle(req, res);
  } catch {
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Unexpected server error.');
  }
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => process.exit(0), 2_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
